async (cursor, num, params) => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const pageStart = Date.now();
  const shown = sel => [...document.querySelectorAll(sel)].find(e => e.getClientRects().length) || null;
  const INPUT = 'form [role="textbox"][contenteditable="true"]';
  const label = (...ls) => [...document.querySelectorAll('button')].find(b => b.getClientRects().length && ls.includes(b.getAttribute('aria-label')));
  // 一次提交 = 一段 #imagine-masonry-section-N：顶上一个提示词标签（data-prompt-pill），下面是图（每张一个 data-masonry-key）
  const sections = () => [...document.querySelectorAll('[id^="imagine-masonry-section-"]')];
  const head = String(params.prompt).trim().slice(0, 40);
  const QUOTA = /limit|上限|额度|升级|upgrade|rate/i;
  if (!cursor) {
    // 常驻标签：不在 Imagine 页就点侧栏「Imagine」（页内跳转），点不到才整页去 /imagine
    if (!/^\/imagine\/?$/.test(location.pathname)) {
      const a = [...document.querySelectorAll('a')].find(e => e.getClientRects().length && e.innerText.trim() === 'Imagine');
      if (a) a.click(); else location.assign('/imagine');
      const t1 = Date.now();
      while (Date.now() - t1 < 8000 && !(/^\/imagine\/?$/.test(location.pathname) && shown(INPUT))) await sleep(300);
    }
    let ed = null;
    for (let i = 0; i < 30 && !(ed = shown(INPUT)); i++) await sleep(300);
    if (!ed) throw new Error('[grok-image] 没找到 Imagine 输入框 url=' + location.pathname);
    const radio = t => [...document.querySelectorAll('[role="radio"]')].find(b => b.getClientRects().length && b.innerText.trim() === t);
    // 模式：「图片」（不是视频）、「质量 2.0」（比「速度」细，像素画边缘更干净）；宽高比 1:1
    for (const t of ['图片', '质量 2.0']) {
      const b = radio(t);
      if (!b) throw new Error('[grok-image] 没找到「' + t + '」选项（界面改了？）');
      if (b.getAttribute('aria-checked') !== 'true') { b.click(); await sleep(400); }
    }
    const ar = label('宽高比', 'Aspect ratio');
    if (ar && !/^1:1/.test(ar.innerText.trim())) {
      ar.click();
      let it = null;
      for (let i = 0; i < 10 && !it; i++) { await sleep(200); it = [...document.querySelectorAll('[role^="menuitem"], [role="option"]')].find(e => /^1:1/.test(e.innerText.trim())); }
      if (!it) throw new Error('[grok-image] 宽高比菜单里没有 1:1');
      it.click(); await sleep(400);
    }
    // 参考图（图生图）：经输入框旁的上传框挂上，等缩略图出来
    if (params.images) {
      const urls = params.images.split('\n').filter(Boolean);
      const fdt = new DataTransfer();
      for (let i = 0; i < urls.length; i++) { const m = /^data:([^;,]+)?(;base64)?,(.*)$/s.exec(urls[i]); if (!m) throw new Error('[grok-image] 参考图要 data URL'); const type = m[1] || 'image/png'; const bin = m[2] ? atob(m[3]) : decodeURIComponent(m[3]); const bytes = new Uint8Array(bin.length); for (let k = 0; k < bin.length; k++) bytes[k] = bin.charCodeAt(k); fdt.items.add(new File([bytes], 'ref' + i + '.' + (type.split('/')[1] || 'png'), { type })); }
      const form = ed.closest('form');
      const thumbs = () => [...form.querySelectorAll('img')].filter(i => i.getClientRects().length).length;
      const before = thumbs();
      const inp = [...form.querySelectorAll('input[type=file]')].find(x => /image/.test(x.accept || '')) || form.querySelector('input[type=file]') || document.querySelector('input[type=file]');
      if (!inp) throw new Error('[grok-image] 没找到上传框（input[type=file]）');
      inp.files = fdt.files; inp.dispatchEvent(new Event('change', { bubbles: true }));
      for (let i = 0; i < 30 && thumbs() < before + urls.length; i++) await sleep(300);
      if (thumbs() < before + urls.length) throw new Error('[grok-image] 参考图没挂到输入框上（输入框里没看到缩略图）');
      await sleep(1500);
    }
    // 写字：tiptap/ProseMirror 编辑器，execCommand insertText（2026-10-22 实测可用）
    ed.focus();
    document.execCommand('selectAll'); document.execCommand('delete');
    document.execCommand('insertText', false, String(params.prompt).trim());
    let send = null;
    const t0 = Date.now();
    while (Date.now() - t0 < 10000) {
      send = label('提交', 'Submit');
      if (send && !send.disabled) break;
      await sleep(300);
    }
    if (!send || send.disabled) throw new Error('[grok-image] 写入后 10s 提交按钮仍不可用（输入框字数 ' + ed.innerText.length + '）');
    window.__grkBefore = new Set(sections().map(s => s.querySelector('[data-prompt-pill]')?.innerText + '|' + [...s.querySelectorAll('[data-masonry-key]')].map(e => e.getAttribute('data-masonry-key')).join(',')));
    window.__grkBeforeKeys = new Set([...document.querySelectorAll('[data-masonry-key]')].map(e => e.getAttribute('data-masonry-key')));
    send.click();
    window.__grkT0 = Date.now();
    window.__grkSig = null; window.__grkSince = 0;
  }
  const deadline = Math.min(Date.now() + 22000, pageStart + 26000);
  while (Date.now() < deadline) {
    // 这一轮的段：提示词标签以我们的提示词开头、且里面有提交前没有的图
    const sec = sections().find(s => (s.querySelector('[data-prompt-pill]')?.innerText || '').trim().startsWith(head) && [...s.querySelectorAll('[data-masonry-key]')].some(e => !window.__grkBeforeKeys.has(e.getAttribute('data-masonry-key'))));
    if (sec) {
      const cards = [...sec.querySelectorAll('[data-masonry-key]')].filter(e => !window.__grkBeforeKeys.has(e.getAttribute('data-masonry-key')));
      const imgs = cards.map(c => [...c.querySelectorAll('img')].find(i => i.complete && i.naturalWidth >= 400 && /^(data:image|https?:)/.test(i.src))).filter(Boolean);
      const txt = (sec.innerText || '').replace((sec.querySelector('[data-prompt-pill]')?.innerText || ''), '').trim();
      if (!imgs.length && txt && Date.now() - window.__grkT0 > 20000 && !/\d+%/.test(txt)) throw new Error('[grok-image] Grok ' + (QUOTA.test(txt) ? '额度/限制：' : '没出图：') + txt.slice(0, 200));
      // 生成途中每张卡先是占位 / 半成品，全都换成最终图、3s 不再变才收
      const sig = cards.length + ':' + imgs.map(i => i.src.length + '@' + i.src.slice(-24)).join(',');
      if (imgs.length && imgs.length === cards.length && !/\d+%/.test(txt)) {
        if (sig !== window.__grkSig) { window.__grkSig = sig; window.__grkSince = Date.now(); }
        else if (Date.now() - window.__grkSince > 3000) {
          const items = [];
          for (let n = 0; n < imgs.length; n++) {
            const img = imgs[n];
            const k = Math.min(1, 1024 / Math.max(img.naturalWidth, img.naturalHeight));
            const c = document.createElement('canvas');
            c.width = Math.round(img.naturalWidth * k); c.height = Math.round(img.naturalHeight * k);
            c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
            let png;
            try { png = c.toDataURL('image/png').split(',')[1]; } catch (e) { throw new Error('[grok-image] 图画进 canvas 后读不出来（跨域图？src=' + img.src.slice(0, 60) + '）'); }
            items.push({ guid: 'grok-' + cards[n].getAttribute('data-masonry-key'), png, index: String(n) });
          }
          return { items, cursor: '' };
        }
      } else { window.__grkSig = null; }
    }
    await sleep(500);
  }
  if (Date.now() - (window.__grkT0 || pageStart) > 190000) throw new Error('[grok-image] 190s 内没等到图');
  return { items: [], pending: true, cursor: String(Number(cursor || 0) + 1) };
}
